function ProjectGrid() {
  const trackRef = useRef<HTMLDivElement>(null);
  const pausedRef = useRef(false);

  useEffect(() => {
    const track = trackRef.current;
    if (!track || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let frame = 0;
    let previous = performance.now();
    const move = (now: number) => {
      const elapsed = Math.min(now - previous, 32);
      previous = now;
      if (!pausedRef.current) {
        track.scrollLeft += elapsed * 0.035;
        const midpoint = track.scrollWidth / 2;
        if (track.scrollLeft >= midpoint) track.scrollLeft -= midpoint;
      }
      frame = requestAnimationFrame(move);
    };
    frame = requestAnimationFrame(move);
    return () => cancelAnimationFrame(frame);
  }, []);

  const cards = [...projectData, ...projectData];
  return <div className="project-rail-shell mt-10" onMouseEnter={() => { pausedRef.current = true; }} onMouseLeave={() => { pausedRef.current = false; }} onFocusCapture={() => { pausedRef.current = true; }} onBlurCapture={() => { pausedRef.current = false; }} onPointerDown={() => { pausedRef.current = true; }} onPointerUp={() => { pausedRef.current = false; }}>
    <div className="mb-5 flex items-center justify-between gap-5 text-xs uppercase tracking-[0.18em] text-muted-foreground"><span>07 {projectData.length === 1 ? "project" : "projects"}</span><span className="flex items-center gap-2"><span className="h-px w-10 bg-primary/60"/>Scroll</span></div>
    <div ref={trackRef} className="project-rail" aria-label="Portfolio projects">
      {cards.map((p,i)=><a key={`${p.name}-${i}`} href={p.url} target="_blank" rel="noreferrer" aria-hidden={i >= projectData.length ? true : undefined} tabIndex={i >= projectData.length ? -1 : undefined} className="project-cinematic-card group">
        <img src={p.image} width="1200" height="900" loading="lazy" alt={i < projectData.length ? p.alt : ""} className="absolute inset-0 h-full w-full object-cover transition-transform duration-1000 ease-out group-hover:scale-[1.06]"/>
        <span className="absolute inset-0 bg-gradient-to-t from-background via-background/15 to-transparent"/>
        <span className="absolute inset-0 bg-primary/0 transition-colors duration-700 group-hover:bg-primary/10"/>
        <span className="absolute left-5 top-5 rounded-full border border-foreground/20 bg-background/70 px-3 py-1 font-display text-lg text-primary backdrop-blur-md">{String((i % projectData.length) + 1).padStart(2,"0")}</span>
        <span className="absolute inset-x-0 bottom-0 flex items-end justify-between gap-4 p-6 md:p-8"><span><span className="block font-display text-3xl leading-tight text-foreground md:text-4xl">{p.name}</span><span className="mt-2 block text-sm text-foreground/70">{p.sector}</span></span><span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full border border-foreground/25 bg-background/50 backdrop-blur-md transition-all duration-500 group-hover:rotate-45 group-hover:border-primary group-hover:bg-primary"><ArrowUpRight className="size-5 text-foreground"/></span></span>
      </a>)}
    </div>
  </div>;
}

